select public.upsert_bank_question($json${"id":"poet-easy-001","type":"choice","level":"easy","testament":"ot","book":"DAN","chapter":6,"verse_start":10,"verse_end":10,"texts":{"pt":{"prompt":"Quantas vezes por dia se ajoelhava Daniel para orar?","bible_ref":"Daniel 6:10","verse_text":"E Daniel, quando soube que a escritura estava assinada, entrou em sua casa, e com as janelas de seu quarto abertas, voltadas para Jerusalém, punha-se de joelhos três vezes ao dia, e orava, e confessava diante de seu Deus, assim como costumava fazer antes."},"fr":{"prompt":"Combien de fois par jour Daniel se mettait-il à genoux pour prier ?","bible_ref":"Daniel 6:10","verse_text":"Lorsque Daniel sut que le décret était écrit, il se retira dans sa maison, où les fenêtres de la chambre supérieure étaient ouvertes dans la direction de Jérusalem; et trois fois le jour il se mettait à genoux, il priait, et il louait son Dieu, comme il le faisait auparavant."},"en":{"prompt":"How many times a day did Daniel kneel to pray?","bible_ref":"Daniel 6:10","verse_text":"Now when Daniel knew that the writing was signed, he went into his house; and his windows being open in his chamber toward Jerusalem, he kneeled upon his knees three times a day, and prayed, and gave thanks before his God, as he did aforetime."},"es":{"prompt":"¿Cuántas veces al día se arrodillaba Daniel para orar?","bible_ref":"Daniel 6:10","verse_text":"Y Daniel, cuando supo que la escritura estaba firmada, entróse en su casa, y abiertas las ventanas de su cámara que estaban hacia Jerusalem, hincábase de rodillas tres veces al día, y oraba, y confesaba delante de su Dios, como lo solía hacer antes."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Três"},"fr":{"text":"Trois"},"en":{"text":"Three"},"es":{"text":"Tres"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Uma"},"fr":{"text":"Une"},"en":{"text":"One"},"es":{"text":"Una"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Sete"},"fr":{"text":"Sept"},"en":{"text":"Seven"},"es":{"text":"Siete"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Dez"},"fr":{"text":"Dix"},"en":{"text":"Ten"},"es":{"text":"Diez"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"poet-easy-002","type":"choice","level":"easy","testament":"ot","book":"DAN","chapter":6,"verse_start":22,"verse_end":22,"texts":{"pt":{"prompt":"Quem fechou a boca dos leões para não fazerem mal a Daniel?","bible_ref":"Daniel 6:22","verse_text":"Meu Deus enviou seu anjo, que fechou a boca dos leões, para que não me fizessem dano; porque diante dele se achou inocência em mim; e também contra ti, ó rei, não cometi delito algum."},"fr":{"prompt":"Qui a fermé la gueule des lions pour qu’ils ne fassent pas de mal à Daniel ?","bible_ref":"Daniel 6:22","verse_text":"Mon Dieu a envoyé son ange et fermé la gueule des lions, qui ne m’ont fait aucun mal, parce que j’ai été trouvé innocent devant lui; et devant toi non plus, ô roi, je n’ai rien fait de mauvais."},"en":{"prompt":"Who shut the lions’ mouths so that they did not hurt Daniel?","bible_ref":"Daniel 6:22","verse_text":"My God hath sent his angel, and hath shut the lions’ mouths, that they have not hurt me: forasmuch as before him innocency was found in me; and also before thee, O king, have I done no hurt."},"es":{"prompt":"¿Quién cerró la boca de los leones para que no hicieran daño a Daniel?","bible_ref":"Daniel 6:22","verse_text":"El Dios mío envió su ángel, el cual cerró la boca de los leones, para que no me hiciesen mal: porque delante de él se halló en mí justicia: y aun delante de ti, oh rey, yo no he hecho lo que no debiese."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Um anjo enviado por Deus"},"fr":{"text":"Un ange envoyé par Dieu"},"en":{"text":"An angel sent by God"},"es":{"text":"Un ángel enviado por Dios"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"O rei"},"fr":{"text":"Le roi"},"en":{"text":"The king"},"es":{"text":"El rey"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Os soldados"},"fr":{"text":"Les soldats"},"en":{"text":"The soldiers"},"es":{"text":"Los soldados"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"O próprio Daniel"},"fr":{"text":"Daniel lui-même"},"en":{"text":"Daniel himself"},"es":{"text":"El propio Daniel"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"poet-easy-003","type":"choice","level":"easy","testament":"ot","book":"DAN","chapter":3,"verse_start":25,"verse_end":25,"texts":{"pt":{"prompt":"Quantos homens viu o rei a andar no meio do fogo da fornalha?","bible_ref":"Daniel 3:25","verse_text":"Ele disse mais: Eis que vejo quatro homens soltos andando no meio do fogo, e não há neles dano algum; e a aparência do quarto é semelhante a um filho de deuses."},"fr":{"prompt":"Combien d’hommes le roi vit-il marcher au milieu du feu de la fournaise ?","bible_ref":"Daniel 3:25","verse_text":"Il reprit et dit: Eh bien, je vois quatre hommes sans liens, qui marchent au milieu du feu, et qui n’ont point de mal; et la figure du quatrième ressemble à celle d’un fils des dieux."},"en":{"prompt":"How many men did the king see walking in the midst of the fire?","bible_ref":"Daniel 3:25","verse_text":"He answered and said, Lo, I see four men loose, walking in the midst of the fire, and they have no hurt; and the form of the fourth is like the Son of God."},"es":{"prompt":"¿Cuántos hombres vio el rey paseándose en medio del fuego del horno?","bible_ref":"Daniel 3:25","verse_text":"Respondió él y dijo: He aquí que yo veo cuatro varones sueltos, que se pasean en medio del fuego, y ningún daño hay en ellos: y el parecer del cuarto es semejante á hijo de los dioses."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Quatro"},"fr":{"text":"Quatre"},"en":{"text":"Four"},"es":{"text":"Cuatro"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Três"},"fr":{"text":"Trois"},"en":{"text":"Three"},"es":{"text":"Tres"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Dois"},"fr":{"text":"Deux"},"en":{"text":"Two"},"es":{"text":"Dos"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Sete"},"fr":{"text":"Sept"},"en":{"text":"Seven"},"es":{"text":"Siete"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"poet-easy-004","type":"choice","level":"easy","testament":"ot","book":"DAN","chapter":5,"verse_start":5,"verse_end":5,"texts":{"pt":{"prompt":"Durante o banquete do rei, o que apareceu a escrever na parede do palácio?","bible_ref":"Daniel 5:5","verse_text":"Naquela mesma hora saíram dedos de uma mão de homem, e escreveram diante do castiçal na caiadura da parede do palácio real, e o rei viu parte da mão que estava escrevendo."},"fr":{"prompt":"Pendant le festin du roi, qu’est-ce qui apparut pour écrire sur la muraille du palais ?","bible_ref":"Daniel 5:5","verse_text":"En ce moment, apparurent les doigts d’une main d’homme, et ils écrivirent, en face du chandelier, sur la chaux de la muraille du palais royal. Le roi vit cette extrémité de main qui écrivait."},"en":{"prompt":"During the king’s feast, what appeared and wrote on the wall of the palace?","bible_ref":"Daniel 5:5","verse_text":"In the same hour came forth fingers of a man’s hand, and wrote over against the candlestick upon the plaister of the wall of the king’s palace: and the king saw the part of the hand that wrote."},"es":{"prompt":"Durante el banquete del rey, ¿qué apareció escribiendo en la pared del palacio?","bible_ref":"Daniel 5:5","verse_text":"En aquella misma hora salieron unos dedos de mano de hombre, y escribían delante del candelero sobre lo encalado de la pared del palacio real, y el rey veía la palma de la mano que escribía."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Os dedos de uma mão"},"fr":{"text":"Les doigts d’une main"},"en":{"text":"The fingers of a hand"},"es":{"text":"Los dedos de una mano"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Uma pomba"},"fr":{"text":"Une colombe"},"en":{"text":"A dove"},"es":{"text":"Una paloma"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Um anjo com uma espada"},"fr":{"text":"Un ange avec une épée"},"en":{"text":"An angel with a sword"},"es":{"text":"Un ángel con una espada"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Uma serpente"},"fr":{"text":"Un serpent"},"en":{"text":"A serpent"},"es":{"text":"Una serpiente"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"poet-easy-005","type":"choice","level":"easy","testament":"ot","book":"JON","chapter":1,"verse_start":2,"verse_end":2,"texts":{"pt":{"prompt":"Para que grande cidade mandou Deus Jonas?","bible_ref":"Jonas 1:2","verse_text":"Levanta-te, vai à grande cidade de Nínive, e prega contra ela; porque sua maldade subiu diante de mim."},"fr":{"prompt":"Dans quelle grande ville Dieu envoya-t-il Jonas ?","bible_ref":"Jonas 1:2","verse_text":"Lève-toi, va à Ninive, la grande ville, et crie contre elle! Car sa méchanceté est montée jusqu’à moi."},"en":{"prompt":"To which great city did God send Jonah?","bible_ref":"Jonah 1:2","verse_text":"Arise, go to Nineveh, that great city, and cry against it; for their wickedness is come up before me."},"es":{"prompt":"¿A qué gran ciudad envió Dios a Jonás?","bible_ref":"Jonás 1:2","verse_text":"Levántate, y ve á Nínive, ciudad grande, y pregona contra ella; porque su maldad ha subido delante de mí."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Nínive"},"fr":{"text":"Ninive"},"en":{"text":"Nineveh"},"es":{"text":"Nínive"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Jerusalém"},"fr":{"text":"Jérusalem"},"en":{"text":"Jerusalem"},"es":{"text":"Jerusalem"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Babilónia"},"fr":{"text":"Babylone"},"en":{"text":"Babylon"},"es":{"text":"Babilonia"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Belém"},"fr":{"text":"Bethléhem"},"en":{"text":"Bethlehem"},"es":{"text":"Beth-lehem"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"poet-easy-006","type":"choice","level":"easy","testament":"ot","book":"JON","chapter":2,"verse_start":1,"verse_end":1,"texts":{"pt":{"prompt":"Jonas esteve dentro da barriga de que animal?","bible_ref":"Jonas 2:1","verse_text":"E Jonas orou ao SENHOR seu Deus, desde as entranhas do peixe,"},"fr":{"prompt":"Dans le ventre de quel animal Jonas s’est-il trouvé ?","bible_ref":"Jonas 2:1","verse_text":"L’Éternel fit venir un grand poisson pour engloutir Jonas, et Jonas fut dans le ventre du poisson trois jours et trois nuits."},"en":{"prompt":"Inside the belly of which animal was Jonah?","bible_ref":"Jonah 2:1","verse_text":"Then Jonah prayed unto the LORD his God out of the fish’s belly,"},"es":{"prompt":"¿En el vientre de qué animal estuvo Jonás?","bible_ref":"Jonás 2:1","verse_text":"Mas Jehová había prevenido un gran pez que tragase á Jonás: y estuvo Jonás en el vientre del pez tres días y tres noches."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Um peixe"},"fr":{"text":"Un poisson"},"en":{"text":"A fish"},"es":{"text":"Un pez"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Um leão"},"fr":{"text":"Un lion"},"en":{"text":"A lion"},"es":{"text":"Un león"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Um urso"},"fr":{"text":"Un ours"},"en":{"text":"A bear"},"es":{"text":"Un oso"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Um camelo"},"fr":{"text":"Un chameau"},"en":{"text":"A camel"},"es":{"text":"Un camello"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"poet-easy-007","type":"choice","level":"easy","testament":"ot","book":"JOB","chapter":42,"verse_start":10,"verse_end":10,"texts":{"pt":{"prompt":"No fim da história, quanto deu o SENHOR a Jó?","bible_ref":"Jó 42:10","verse_text":"E o SENHOR livrou Jó de seu infortúnio, enquanto ele orava pelos seus amigos; e o SENHOR acrescentou a Jó o dobro de tudo quanto ele antes possuía."},"fr":{"prompt":"À la fin de l’histoire, combien l’Éternel donna-t-il à Job ?","bible_ref":"Job 42:10","verse_text":"L’Éternel rétablit Job dans son premier état, quand Job eut prié pour ses amis; et l’Éternel lui accorda le double de tout ce qu’il avait possédé."},"en":{"prompt":"At the end of the story, how much did the LORD give Job?","bible_ref":"Job 42:10","verse_text":"And the LORD turned the captivity of Job, when he prayed for his friends: also the LORD gave Job twice as much as he had before."},"es":{"prompt":"Al final de la historia, ¿cuánto le dio Jehová a Job?","bible_ref":"Job 42:10","verse_text":"Y mudó Jehová la aflicción de Job, orando él por sus amigos: y aumentó al doble todas las cosas que habían sido de Job."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"O dobro do que tinha antes"},"fr":{"text":"Le double de ce qu’il avait avant"},"en":{"text":"Twice as much as he had before"},"es":{"text":"El doble de lo que tenía antes"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Metade do que tinha antes"},"fr":{"text":"La moitié de ce qu’il avait avant"},"en":{"text":"Half of what he had before"},"es":{"text":"La mitad de lo que tenía antes"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Exatamente o mesmo"},"fr":{"text":"Exactement la même chose"},"en":{"text":"Exactly the same"},"es":{"text":"Exactamente lo mismo"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Nada"},"fr":{"text":"Rien"},"en":{"text":"Nothing"},"es":{"text":"Nada"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"poet-easy-008","type":"choice","level":"easy","testament":"ot","book":"ISA","chapter":7,"verse_start":14,"verse_end":14,"texts":{"pt":{"prompt":"Segundo Isaías, que nome teria o filho que a virgem ia ter?","bible_ref":"Isaías 7:14","verse_text":"Por isso o Senhor, ele mesmo, vos dará um sinal: eis que a virgem conceberá, e fará nascer um filho, e ela chamará seu nome Emanuel."},"fr":{"prompt":"Selon Ésaïe, quel nom aurait le fils que la jeune fille allait enfanter ?","bible_ref":"Ésaïe 7:14","verse_text":"C’est pourquoi le Seigneur lui-même vous donnera un signe, Voici, la jeune fille deviendra enceinte, elle enfantera un fils, Et elle lui donnera le nom d’Emmanuel."},"en":{"prompt":"According to Isaiah, what name would the son born of the virgin have?","bible_ref":"Isaiah 7:14","verse_text":"Therefore the Lord himself shall give you a sign; Behold, a virgin shall conceive, and bear a son, and shall call his name Immanuel."},"es":{"prompt":"Según Isaías, ¿qué nombre tendría el hijo que daría a luz la virgen?","bible_ref":"Isaías 7:14","verse_text":"Por tanto el mismo Señor os dará señal: He aquí que la virgen concebirá, y parirá hijo, y llamará su nombre Emmanuel."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Emanuel"},"fr":{"text":"Emmanuel"},"en":{"text":"Immanuel"},"es":{"text":"Emmanuel"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Samuel"},"fr":{"text":"Samuel"},"en":{"text":"Samuel"},"es":{"text":"Samuel"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Daniel"},"fr":{"text":"Daniel"},"en":{"text":"Daniel"},"es":{"text":"Daniel"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Isaque"},"fr":{"text":"Isaac"},"en":{"text":"Isaac"},"es":{"text":"Isaac"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"poet-easy-009","type":"choice","level":"easy","testament":"ot","book":"ISA","chapter":6,"verse_start":8,"verse_end":8,"texts":{"pt":{"prompt":"Quando o Senhor perguntou «A quem enviarei?», o que respondeu Isaías?","bible_ref":"Isaías 6:8","verse_text":"Depois disso ouvi a voz do Senhor, que dizia: A quem enviarei? E quem irá por nós? Então eu disse: Eis-me aqui! Envia-me!"},"fr":{"prompt":"Quand le Seigneur demanda « Qui enverrai-je ? », que répondit Ésaïe ?","bible_ref":"Ésaïe 6:8","verse_text":"J’entendis la voix du Seigneur, disant: Qui enverrai-je, et qui marchera pour nous? Je répondis: Me voici, envoie-moi."},"en":{"prompt":"When the Lord asked “Whom shall I send?”, what did Isaiah answer?","bible_ref":"Isaiah 6:8","verse_text":"Also I heard the voice of the Lord, saying, Whom shall I send, and who will go for us? Then said I, Here am I; send me."},"es":{"prompt":"Cuando el Señor preguntó «¿A quién enviaré?», ¿qué respondió Isaías?","bible_ref":"Isaías 6:8","verse_text":"Después oí la voz del Señor, que decía: ¿A quién enviaré, y quién nos irá? Entonces respondí yo: Heme aquí, envíame á mí."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Eis-me aqui, envia-me!"},"fr":{"text":"Me voici, envoie-moi."},"en":{"text":"Here am I; send me."},"es":{"text":"Heme aquí, envíame a mí."}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Envia outra pessoa!"},"fr":{"text":"Envoie quelqu’un d’autre !"},"en":{"text":"Send someone else!"},"es":{"text":"¡Envía a otro!"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Não sei falar."},"fr":{"text":"Je ne sais pas parler."},"en":{"text":"I cannot speak."},"es":{"text":"No sé hablar."}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Tenho medo."},"fr":{"text":"J’ai peur."},"en":{"text":"I am afraid."},"es":{"text":"Tengo miedo."}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"poet-easy-010","type":"choice","level":"easy","testament":"ot","book":"PRO","chapter":1,"verse_start":1,"verse_end":1,"texts":{"pt":{"prompt":"De que rei, filho de David, são os provérbios do livro de Provérbios?","bible_ref":"Provérbios 1:1","verse_text":"Provérbios de Salomão, filho de Davi, rei de Israel."},"fr":{"prompt":"De quel roi, fils de David, sont les proverbes du livre des Proverbes ?","bible_ref":"Proverbes 1:1","verse_text":"Proverbes de Salomon, fils de David, roi d’Israël,"},"en":{"prompt":"Which king, the son of David, wrote the proverbs of the book of Proverbs?","bible_ref":"Proverbs 1:1","verse_text":"The proverbs of Solomon the son of David, king of Israel;"},"es":{"prompt":"¿De qué rey, hijo de David, son los proverbios del libro de Proverbios?","bible_ref":"Proverbios 1:1","verse_text":"Los proverbios de Salomón, hijo de David, rey de Israel:"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Salomão"},"fr":{"text":"Salomon"},"en":{"text":"Solomon"},"es":{"text":"Salomón"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Saul"},"fr":{"text":"Saül"},"en":{"text":"Saul"},"es":{"text":"Saúl"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Ezequias"},"fr":{"text":"Ézéchias"},"en":{"text":"Hezekiah"},"es":{"text":"Ezechîas"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Josias"},"fr":{"text":"Josias"},"en":{"text":"Josiah"},"es":{"text":"Josías"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"poet-easy-011","type":"choice","level":"easy","testament":"ot","book":"ECC","chapter":3,"verse_start":1,"verse_end":1,"texts":{"pt":{"prompt":"Segundo Eclesiastes, o que há para todas as coisas debaixo do céu?","bible_ref":"Eclesiastes 3:1","verse_text":"Para todas as coisas há um tempo determinado, e todo propósito abaixo do céu tem seu tempo."},"fr":{"prompt":"Selon l’Ecclésiaste, qu’y a-t-il pour toute chose sous les cieux ?","bible_ref":"Ecclésiaste 3:1","verse_text":"Il y a un temps pour tout, un temps pour toute chose sous les cieux:"},"en":{"prompt":"According to Ecclesiastes, what is there for every purpose under heaven?","bible_ref":"Ecclesiastes 3:1","verse_text":"To every thing there is a season, and a time to every purpose under the heaven:"},"es":{"prompt":"Según Eclesiastés, ¿qué hay para todo lo que se quiere debajo del cielo?","bible_ref":"Eclesiastés 3:1","verse_text":"Para todas las cosas hay sazón, y todo lo que se quiere debajo del cielo, tiene su tiempo:"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Um tempo"},"fr":{"text":"Un temps"},"en":{"text":"A time"},"es":{"text":"Un tiempo"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Um preço"},"fr":{"text":"Un prix"},"en":{"text":"A price"},"es":{"text":"Un precio"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Um rei"},"fr":{"text":"Un roi"},"en":{"text":"A king"},"es":{"text":"Un rey"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Um segredo"},"fr":{"text":"Un secret"},"en":{"text":"A secret"},"es":{"text":"Un secreto"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"poet-easy-012","type":"choice","level":"easy","testament":"ot","book":"JER","chapter":1,"verse_start":6,"verse_end":6,"texts":{"pt":{"prompt":"Quando Deus o chamou para ser profeta, o que disse Jeremias que era?","bible_ref":"Jeremias 1:6","verse_text":"E eu disse: Ah! Senhor DEUS! Eis que não sei falar, pois sou um menino."},"fr":{"prompt":"Quand Dieu l’appela à être prophète, que dit Jérémie qu’il était ?","bible_ref":"Jérémie 1:6","verse_text":"Je répondis: Ah! Seigneur Éternel! Voici, je ne sais point parler, car je suis un enfant."},"en":{"prompt":"When God called him to be a prophet, what did Jeremiah say he was?","bible_ref":"Jeremiah 1:6","verse_text":"Then said I, Ah, Lord GOD! behold, I cannot speak: for I am a child."},"es":{"prompt":"Cuando Dios lo llamó para ser profeta, ¿qué dijo Jeremías que era?","bible_ref":"Jeremías 1:6","verse_text":"Y yo dije: ¡Ah! ¡ah! ¡Señor Jehová! He aquí, no sé hablar, porque soy niño."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Um menino"},"fr":{"text":"Un enfant"},"en":{"text":"A child"},"es":{"text":"Un niño"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Um velho"},"fr":{"text":"Un vieillard"},"en":{"text":"An old man"},"es":{"text":"Un anciano"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Um rei"},"fr":{"text":"Un roi"},"en":{"text":"A king"},"es":{"text":"Un rey"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Um soldado"},"fr":{"text":"Un soldat"},"en":{"text":"A soldier"},"es":{"text":"Un soldado"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"poet-easy-013","type":"order","level":"easy","testament":"ot","book":"DAN","chapter":6,"verse_start":10,"verse_end":10,"texts":{"pt":{"prompt":"Ordena estes episódios pela ordem em que aconteceram.","bible_ref":"Daniel 6:10","verse_text":null},"fr":{"prompt":"Mets ces épisodes dans l’ordre où ils se sont produits.","bible_ref":"Daniel 6:10","verse_text":null},"en":{"prompt":"Put these episodes in the order they happened.","bible_ref":"Daniel 6:10","verse_text":null},"es":{"prompt":"Ordena estos episodios según ocurrieron.","bible_ref":"Daniel 6:10","verse_text":null}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"Daniel ora com as janelas abertas","ref":"Daniel 6:10"},"fr":{"text":"Daniel prie, fenêtres ouvertes","ref":"Daniel 6:10"},"en":{"text":"Daniel prays with his windows open","ref":"Daniel 6:10"},"es":{"text":"Daniel ora con las ventanas abiertas","ref":"Daniel 6:10"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Daniel é lançado na cova dos leões","ref":"Daniel 6:16"},"fr":{"text":"Daniel est jeté dans la fosse aux lions","ref":"Daniel 6:16"},"en":{"text":"Daniel is cast into the lions’ den","ref":"Daniel 6:16"},"es":{"text":"Daniel es echado en el foso de los leones","ref":"Daniel 6:16"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Uma pedra tapa a entrada da cova","ref":"Daniel 6:17"},"fr":{"text":"Une pierre ferme l’ouverture de la fosse","ref":"Daniel 6:17"},"en":{"text":"A stone is laid on the mouth of the den","ref":"Daniel 6:17"},"es":{"text":"Una piedra tapa la puerta del foso","ref":"Daniel 6:17"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Daniel sai da cova sem nenhum mal","ref":"Daniel 6:23"},"fr":{"text":"Daniel sort de la fosse sans blessure","ref":"Daniel 6:23"},"en":{"text":"Daniel comes out of the den unhurt","ref":"Daniel 6:23"},"es":{"text":"Daniel sale del foso sin ningún daño","ref":"Daniel 6:23"}}}]}$json$::jsonb);
