select public.upsert_bank_question($json${"id":"poet-medium-001","type":"choice","level":"medium","testament":"ot","book":"PSA","chapter":1,"verse_start":3,"verse_end":3,"texts":{"pt":{"prompt":"No Salmo 1, o homem bem-aventurado é comparado a quê?","bible_ref":"Salmos 1:3","verse_text":"Porque ele será como uma árvore, plantada junto a ribeiros de águas, que dá fruto a seu devido tempo, e suas folhas não caem; e tudo quanto fizer prosperará."},"fr":{"prompt":"Dans le Psaume 1, à quoi est comparé l’homme heureux ?","bible_ref":"Psaumes 1:3","verse_text":"Il est comme un arbre planté près d’un courant d’eau, Qui donne son fruit en sa saison, Et dont le feuillage ne se flétrit point: Tout ce qu’il fait lui réussit."},"en":{"prompt":"In Psalm 1, what is the blessed man compared to?","bible_ref":"Psalms 1:3","verse_text":"And he shall be like a tree planted by the rivers of water, that bringeth forth his fruit in his season; his leaf also shall not wither; and whatsoever he doeth shall prosper."},"es":{"prompt":"En el Salmo 1, ¿a qué se compara el varón bienaventurado?","bible_ref":"Salmos 1:3","verse_text":"Y será como el árbol plantado junto á arroyos de aguas, que da su fruto en su tiempo, y su hoja no cae; y todo lo que hace, prosperará."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Uma árvore plantada junto à água"},"fr":{"text":"Un arbre planté près de l’eau"},"en":{"text":"A tree planted by the water"},"es":{"text":"Un árbol plantado junto a las aguas"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Uma casa construída sobre a rocha"},"fr":{"text":"Une maison bâtie sur le roc"},"en":{"text":"A house built on the rock"},"es":{"text":"Una casa edificada sobre la roca"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Uma estrela no céu"},"fr":{"text":"Une étoile dans le ciel"},"en":{"text":"A star in the sky"},"es":{"text":"Una estrella en el cielo"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Uma torre forte"},"fr":{"text":"Une tour forte"},"en":{"text":"A strong tower"},"es":{"text":"Una torre fuerte"}}}]}$json$::jsonb);
