select public.upsert_bank_question($json${"id":"poet-medium-003","type":"choice","level":"medium","testament":"ot","book":"DAN","chapter":1,"verse_start":12,"verse_end":12,"texts":{"pt":{"prompt":"Durante o teste de dez dias, o que pediu Daniel para comer?","bible_ref":"Daniel 1:12","verse_text":"Faze um teste, eu te peço, com teus servos por dez dias, e dê-nos legumes para comer, e água para beber."},"fr":{"prompt":"Pendant l’épreuve de dix jours, que demanda Daniel à manger ?","bible_ref":"Daniel 1:12","verse_text":"Éprouve tes serviteurs pendant dix jours, et qu’on nous donne des légumes à manger et de l’eau à boire;"},"en":{"prompt":"During the ten-day test, what did Daniel ask to eat?","bible_ref":"Daniel 1:12","verse_text":"Prove thy servants, I beseech thee, ten days; and let them give us pulse to eat, and water to drink."},"es":{"prompt":"Durante la prueba de diez días, ¿qué pidió Daniel para comer?","bible_ref":"Daniel 1:12","verse_text":"Prueba, te ruego, tus siervos diez días, y dennos legumbres á comer, y agua á beber."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Legumes"},"fr":{"text":"Des légumes"},"en":{"text":"Pulse (vegetables)"},"es":{"text":"Legumbres"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Carne"},"fr":{"text":"De la viande"},"en":{"text":"Meat"},"es":{"text":"Carne"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Pão e mel"},"fr":{"text":"Du pain et du miel"},"en":{"text":"Bread and honey"},"es":{"text":"Pan y miel"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Peixe"},"fr":{"text":"Du poisson"},"en":{"text":"Fish"},"es":{"text":"Pescado"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"poet-medium-004","type":"choice","level":"medium","testament":"ot","book":"DAN","chapter":2,"verse_start":32,"verse_end":32,"texts":{"pt":{"prompt":"No sonho de Nabucodonosor, de que era a cabeça da estátua?","bible_ref":"Daniel 2:32","verse_text":"A cabeça da estátua era de ouro puro; seus peito e seus braços, de prata; seu ventre e suas coxas, de bronze;"},"fr":{"prompt":"Dans le songe de Nebucadnetsar, de quoi était faite la tête de la statue ?","bible_ref":"Daniel 2:32","verse_text":"La tête de cette statue était d’or pur; sa poitrine et ses bras étaient d’argent; son ventre et ses cuisses étaient d’airain;"},"en":{"prompt":"In Nebuchadnezzar’s dream, what was the head of the image made of?","bible_ref":"Daniel 2:32","verse_text":"This image’s head was of fine gold, his breast and his arms of silver, his belly and his thighs of brass,"},"es":{"prompt":"En el sueño de Nabucodonosor, ¿de qué era la cabeza de la estatua?","bible_ref":"Daniel 2:32","verse_text":"La cabeza de esta imagen era de fino oro; sus pechos y sus brazos, de plata; su vientre y sus muslos, de metal;"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Ouro"},"fr":{"text":"Or"},"en":{"text":"Gold"},"es":{"text":"Oro"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Prata"},"fr":{"text":"Argent"},"en":{"text":"Silver"},"es":{"text":"Plata"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Ferro"},"fr":{"text":"Fer"},"en":{"text":"Iron"},"es":{"text":"Hierro"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Barro"},"fr":{"text":"Argile"},"en":{"text":"Clay"},"es":{"text":"Barro"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"poet-medium-005","type":"choice","level":"medium","testament":"ot","book":"JON","chapter":1,"verse_start":3,"verse_end":3,"texts":{"pt":{"prompt":"Para onde quis Jonas fugir em vez de ir a Nínive?","bible_ref":"Jonas 1:3","verse_text":"Porém Jonas se levantou para fugir da presença do SENHOR a Társis, e desceu a Jope; e achou um navio que partia para Társis. Então pagou sua passagem e entrou nele, para ir com eles a Társis a fim de se distanciar do SENHOR."},"fr":{"prompt":"Où Jonas voulut-il s’enfuir au lieu d’aller à Ninive ?","bible_ref":"Jonas 1:3","verse_text":"Et Jonas se leva pour s’enfuir à Tarsis, loin de la face de l’Éternel. Il descendit à Japho, et il trouva un navire qui allait à Tarsis; il paya le prix du transport, et s’embarqua pour aller avec les passagers à Tarsis, loin de la face de l’Éternel."},"en":{"prompt":"Where did Jonah try to flee instead of going to Nineveh?","bible_ref":"Jonah 1:3","verse_text":"But Jonah rose up to flee unto Tarshish from the presence of the LORD, and went down to Joppa; and he found a ship going to Tarshish: so he paid the fare thereof, and went down into it, to go with them unto Tarshish from the presence of the LORD."},"es":{"prompt":"¿Adónde quiso huir Jonás en lugar de ir a Nínive?","bible_ref":"Jonás 1:3","verse_text":"Y Jonás se levantó para huir de la presencia de Jehová á Tarsis, y descendió á Joppe; y halló un navío que partía para Tarsis; y pagando su pasaje entró en él, para irse con ellos á Tarsis de delante de Jehová."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Társis"},"fr":{"text":"Tarsis"},"en":{"text":"Tarshish"},"es":{"text":"Tarsis"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Egito"},"fr":{"text":"Égypte"},"en":{"text":"Egypt"},"es":{"text":"Egipto"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Damasco"},"fr":{"text":"Damas"},"en":{"text":"Damascus"},"es":{"text":"Damasco"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Tiro"},"fr":{"text":"Tyr"},"en":{"text":"Tyre"},"es":{"text":"Tiro"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"poet-medium-006","type":"choice","level":"medium","testament":"ot","book":"ISA","chapter":11,"verse_start":6,"verse_end":6,"texts":{"pt":{"prompt":"Na profecia de Isaías 11, com quem morará o lobo?","bible_ref":"Isaías 11:6","verse_text":"E o lobo morará com o cordeiro, e o leopardo se deitará com o cabrito; e o bezerro, o filhote de leão, e o animal cevado andarão juntos, e um menino pequeno os guiará."},"fr":{"prompt":"Dans la prophétie d’Ésaïe 11, avec qui habitera le loup ?","bible_ref":"Ésaïe 11:6","verse_text":"Le loup habitera avec l’agneau, Et la panthère se couchera avec le chevreau; Le veau, le lionceau, et le bétail qu’on engraisse, seront ensemble, Et un petit enfant les conduira."},"en":{"prompt":"In the prophecy of Isaiah 11, with whom shall the wolf dwell?","bible_ref":"Isaiah 11:6","verse_text":"The wolf also shall dwell with the lamb, and the leopard shall lie down with the kid; and the calf and the young lion and the fatling together; and a little child shall lead them."},"es":{"prompt":"En la profecía de Isaías 11, ¿con quién morará el lobo?","bible_ref":"Isaías 11:6","verse_text":"Morará el lobo con el cordero, y el tigre con el cabrito se acostará: el becerro y el león y la bestia doméstica andarán juntos, y un niño los pastoreará."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Com o cordeiro"},"fr":{"text":"Avec l’agneau"},"en":{"text":"With the lamb"},"es":{"text":"Con el cordero"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Com o urso"},"fr":{"text":"Avec l’ours"},"en":{"text":"With the bear"},"es":{"text":"Con el oso"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Com a raposa"},"fr":{"text":"Avec le renard"},"en":{"text":"With the fox"},"es":{"text":"Con la zorra"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Com a águia"},"fr":{"text":"Avec l’aigle"},"en":{"text":"With the eagle"},"es":{"text":"Con el águila"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"poet-medium-007","type":"choice","level":"medium","testament":"ot","book":"JER","chapter":18,"verse_start":2,"verse_end":2,"texts":{"pt":{"prompt":"Deus mandou Jeremias descer à casa de quem, para ouvir as suas palavras?","bible_ref":"Jeremias 18:2","verse_text":"Levanta-te, e desce à casa do oleiro; e ali te farei ouvir minhas palavras."},"fr":{"prompt":"Dans la maison de qui Dieu envoya-t-il Jérémie pour y entendre ses paroles ?","bible_ref":"Jérémie 18:2","verse_text":"Lève-toi, et descends dans la maison du potier; Là, je te ferai entendre mes paroles."},"en":{"prompt":"To whose house did God send Jeremiah to hear his words?","bible_ref":"Jeremiah 18:2","verse_text":"Arise, and go down to the potter’s house, and there I will cause thee to hear my words."},"es":{"prompt":"¿A casa de quién mandó Dios a Jeremías para oír sus palabras?","bible_ref":"Jeremías 18:2","verse_text":"Levántate, y vete á casa del alfarero, y allí te haré oir mis palabras."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Do oleiro"},"fr":{"text":"Du potier"},"en":{"text":"The potter’s"},"es":{"text":"Del alfarero"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Do carpinteiro"},"fr":{"text":"Du charpentier"},"en":{"text":"The carpenter’s"},"es":{"text":"Del carpintero"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Do ferreiro"},"fr":{"text":"Du forgeron"},"en":{"text":"The smith’s"},"es":{"text":"Del herrero"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Do rei"},"fr":{"text":"Du roi"},"en":{"text":"The king’s"},"es":{"text":"Del rey"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"poet-medium-008","type":"choice","level":"medium","testament":"ot","book":"EZK","chapter":37,"verse_start":1,"verse_end":1,"texts":{"pt":{"prompt":"De que estava cheio o vale onde o Espírito do SENHOR pôs Ezequiel?","bible_ref":"Ezequiel 37:1","verse_text":"A mão do SENHOR veio sobre mim, e me tirou por meio do Espírito do SENHOR, e me pôs no meio de um vale que estava cheio de ossos."},"fr":{"prompt":"De quoi était remplie la vallée où l’Éternel déposa Ézéchiel ?","bible_ref":"Ézéchiel 37:1","verse_text":"La main de l’Éternel fut sur moi, et l’Éternel me transporta en esprit, et me déposa dans le milieu d’une vallée remplie d’ossements."},"en":{"prompt":"What was the valley full of, where the LORD set Ezekiel down?","bible_ref":"Ezekiel 37:1","verse_text":"The hand of the LORD was upon me, and carried me out in the spirit of the LORD, and set me down in the midst of the valley which was full of bones,"},"es":{"prompt":"¿De qué estaba lleno el valle donde Jehová puso a Ezequiel?","bible_ref":"Ezequiel 37:1","verse_text":"Y la mano de Jehová fué sobre mí, y sacóme en espíritu de Jehová, y púsome en medio de un campo que estaba lleno de huesos."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"De ossos"},"fr":{"text":"D’ossements"},"en":{"text":"Bones"},"es":{"text":"De huesos"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"De pedras"},"fr":{"text":"De pierres"},"en":{"text":"Stones"},"es":{"text":"De piedras"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"De serpentes"},"fr":{"text":"De serpents"},"en":{"text":"Serpents"},"es":{"text":"De serpientes"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"De soldados"},"fr":{"text":"De soldats"},"en":{"text":"Soldiers"},"es":{"text":"De soldados"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"poet-medium-009","type":"choice","level":"medium","testament":"ot","book":"MAL","chapter":3,"verse_start":10,"verse_end":10,"texts":{"pt":{"prompt":"Em Malaquias, o que manda Deus trazer à casa do tesouro?","bible_ref":"Malaquias 3:10","verse_text":"Trazei todos os dízimos à casa do tesouro, para que haja alimento em minha casa; e provai-me nisto, diz o SENHOR dos exércitos, se não vos abrir as janelas dos céus, e derramar sobre vós bênção transbordante."},"fr":{"prompt":"Dans Malachie, que demande Dieu d’apporter à la maison du trésor ?","bible_ref":"Malachie 3:10","verse_text":"Apportez à la maison du trésor toutes les dîmes, Afin qu’il y ait de la nourriture dans ma maison; Mettez-moi de la sorte à l’épreuve, Dit l’Éternel des armées. Et vous verrez si je n’ouvre pas pour vous les écluses des cieux, Si je ne répands pas sur vous la bénédiction en abondance."},"en":{"prompt":"In Malachi, what does God tell the people to bring into the storehouse?","bible_ref":"Malachi 3:10","verse_text":"Bring ye all the tithes into the storehouse, that there may be meat in mine house, and prove me now herewith, saith the LORD of hosts, if I will not open you the windows of heaven, and pour you out a blessing, that there shall not be room enough to receive it."},"es":{"prompt":"En Malaquías, ¿qué manda Dios traer al alfolí?","bible_ref":"Malaquías 3:10","verse_text":"Traed todos los diezmos al alfolí, y haya alimento en mi casa; y probadme ahora en esto, dice Jehová de los ejércitos, si no os abriré las ventanas de los cielos, y vaciaré sobre vosotros bendición hasta que sobreabunde."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Todos os dízimos"},"fr":{"text":"Toutes les dîmes"},"en":{"text":"All the tithes"},"es":{"text":"Todos los diezmos"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Todas as armas"},"fr":{"text":"Toutes les armes"},"en":{"text":"All the weapons"},"es":{"text":"Todas las armas"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Todos os ídolos"},"fr":{"text":"Toutes les idoles"},"en":{"text":"All the idols"},"es":{"text":"Todos los ídolos"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Todos os rolos da lei"},"fr":{"text":"Tous les rouleaux de la loi"},"en":{"text":"All the scrolls of the law"},"es":{"text":"Todos los rollos de la ley"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"poet-medium-010","type":"choice","level":"medium","testament":"ot","book":"ZEC","chapter":9,"verse_start":9,"verse_end":9,"texts":{"pt":{"prompt":"Segundo Zacarias, montado em que animal viria o rei de Sião, humilde?","bible_ref":"Zacarias 9:9","verse_text":"Alegra-te muito, ó filha de Sião; dá vozes de júbilo, ó filha de Jerusalém; eis que teu rei virá a ti, justo e salvador, humilde, e montado sobre um asno, sobre um jumentinho, filho de jumenta."},"fr":{"prompt":"Selon Zacharie, sur quel animal viendrait le roi de Sion, humble ?","bible_ref":"Zacharie 9:9","verse_text":"Sois transportée d’allégresse, fille de Sion! Pousse des cris de joie, fille de Jérusalem! Voici, ton roi vient à toi; Il est juste et victorieux, Il est humble et monté sur un âne, Sur un âne, le petit d’une ânesse."},"en":{"prompt":"According to Zechariah, riding on what animal would the lowly king of Zion come?","bible_ref":"Zechariah 9:9","verse_text":"Rejoice greatly, O daughter of Zion; shout, O daughter of Jerusalem: behold, thy King cometh unto thee: he is just, and having salvation; lowly, and riding upon an ass, and upon a colt the foal of an ass."},"es":{"prompt":"Según Zacarías, ¿montado en qué animal vendría el rey de Sión, humilde?","bible_ref":"Zacarías 9:9","verse_text":"Alégrate mucho, hija de Sión; da voces de júbilo, hija de Jerusalem: he aquí, tu rey vendrá á ti, justo y salvador, humilde, y cabalgando sobre un asno, así sobre un pollino hijo de asna."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Um jumento"},"fr":{"text":"Un âne"},"en":{"text":"A donkey"},"es":{"text":"Un asno"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Um cavalo"},"fr":{"text":"Un cheval"},"en":{"text":"A horse"},"es":{"text":"Un caballo"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Um camelo"},"fr":{"text":"Un chameau"},"en":{"text":"A camel"},"es":{"text":"Un camello"}}},{"position":4,"is_correct":false,"tex