select public.upsert_bank_question($json${"id":"poet-medium-011","type":"choice","level":"medium","testament":"ot","book":"MIC","chapter":4,"verse_start":3,"verse_end":3,"texts":{"pt":{"prompt":"Na profecia de Miqueias, em que transformarão as nações as suas espadas?","bible_ref":"Miqueias 4:3","verse_text":"E ele julgará entre muitos povos, e corrigirá poderosas nações até muito longe; e adaptarão suas espadas para enxadas, e suas lanças para foices; nação não erguerá espada contra nação, nem mais aprenderão a fazer guerra."},"fr":{"prompt":"Dans la prophétie de Michée, en quoi les nations forgeront-elles leurs glaives ?","bible_ref":"Michée 4:3","verse_text":"Il sera le juge d’un grand nombre de peuples, L’arbitre de nations puissantes, lointaines. De leurs glaives ils forgeront des hoyaux, Et de leurs lances des serpes; Une nation ne tirera plus l’épée contre une autre, Et l’on n’apprendra plus la guerre."},"en":{"prompt":"In Micah’s prophecy, what shall the nations beat their swords into?","bible_ref":"Micah 4:3","verse_text":"And he shall judge among many people, and rebuke strong nations afar off; and they shall beat their swords into plowshares, and their spears into pruninghooks: nation shall not lift up a sword against nation, neither shall they learn war any more."},"es":{"prompt":"En la profecía de Miqueas, ¿en qué convertirán las naciones sus espadas?","bible_ref":"Miqueas 4:3","verse_text":"Y juzgará entre muchos pueblos, y corregirá fuertes gentes hasta muy lejos: y martillarán sus espadas para azadones, y sus lanzas para hoces: no alzará espada gente contra gente, ni más se ensayarán para la guerra."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Enxadas"},"fr":{"text":"Des hoyaux"},"en":{"text":"Plowshares"},"es":{"text":"Azadones"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Escudos"},"fr":{"text":"Des boucliers"},"en":{"text":"Shields"},"es":{"text":"Escudos"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Coroas"},"fr":{"text":"Des couronnes"},"en":{"text":"Crowns"},"es":{"text":"Coronas"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Correntes"},"fr":{"text":"Des chaînes"},"en":{"text":"Chains"},"es":{"text":"Cadenas"}}}]}$json$::jsonb);
