select public.upsert_bank_question($json${"id":"poet-medium-017","type":"verse","level":"medium","testament":"ot","book":"MIC","chapter":6,"verse_start":8,"verse_end":8,"texts":{"pt":{"prompt":"Ele já declarou a ti, ó ser humano, o que é bom; e que mais o SENHOR pede de ti, a não ser fazer o que é justo, amar a bondade, e _____ humildemente com teu Deus?","bible_ref":"Miqueias 6:8","verse_text":"Ele já declarou a ti, ó ser humano, o que é bom; e que mais o SENHOR pede de ti, a não ser fazer o que é justo, amar a bondade, e andar humildemente com teu Deus?"},"fr":{"prompt":"On t’a fait connaître, ô homme, ce qui est bien; Et ce que l’Éternel demande de toi, C’est que tu pratiques la justice, Que tu aimes la miséricorde, Et que tu _____ humblement avec ton Dieu.","bible_ref":"Michée 6:8","verse_text":"On t’a fait connaître, ô homme, ce qui est bien; Et ce que l’Éternel demande de toi, C’est que tu pratiques la justice, Que tu aimes la miséricorde, Et que tu marches humblement avec ton Dieu."},"en":{"prompt":"He hath shewed thee, O man, what is good; and what doth the LORD require of thee, but to do justly, and to love mercy, and to _____ humbly with thy God?","bible_ref":"Micah 6:8","verse_text":"He hath shewed thee, O man, what is good; and what doth the LORD require of thee, but to do justly, and to love mercy, and to walk humbly with thy God?"},"es":{"prompt":"Oh hombre, él te ha declarado qué sea lo bueno, y qué pida de ti Jehová: solamente hacer juicio, y amar misericordia, y humillarte para _____ con tu Dios.","bible_ref":"Miqueas 6:8","verse_text":"Oh hombre, él te ha declarado qué sea lo bueno, y qué pida de ti Jehová: solamente hacer juicio, y amar misericordia, y humillarte para andar con tu Dios."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"andar"},"fr":{"text":"marches"},"en":{"text":"walk"},"es":{"text":"andar"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"falar"},"fr":{"text":"parles"},"en":{"text":"talk"},"es":{"text":"hablar"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"viver"},"fr":{"text":"vives"},"en":{"text":"live"},"es":{"text":"vivir"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"cantar"},"fr":{"text":"chantes"},"en":{"text":"sing"},"es":{"text":"cantar"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"poet-medium-018","type":"verse","level":"medium","testament":"ot","book":"ISA","chapter":53,"verse_start":6,"verse_end":6,"texts":{"pt":{"prompt":"Todos nós andávamos sem rumo como _____; cada um se desviava por seu caminho; porém o SENHOR fez vir sobre ele a perversidade de todos nós.","bible_ref":"Isaías 53:6","verse_text":"Todos nós andávamos sem rumo como ovelhas; cada um se desviava por seu caminho; porém o SENHOR fez vir sobre ele a perversidade de todos nós."},"fr":{"prompt":"Nous étions tous errants comme des _____, Chacun suivait sa propre voie; Et l’Éternel a fait retomber sur lui l’iniquité de nous tous.","bible_ref":"Ésaïe 53:6","verse_text":"Nous étions tous errants comme des brebis, Chacun suivait sa propre voie; Et l’Éternel a fait retomber sur lui l’iniquité de nous tous."},"en":{"prompt":"All we like _____ have gone astray; we have turned every one to his own way; and the LORD hath laid on him the iniquity of us all.","bible_ref":"Isaiah 53:6","verse_text":"All we like sheep have gone astray; we have turned every one to his own way; and the LORD hath laid on him the iniquity of us all."},"es":{"prompt":"Todos nosotros nos descarriamos como _____, cada cual se apartó por su camino: mas Jehová cargó en él el pecado de todos nosotros.","bible_ref":"Isaías 53:6","verse_text":"Todos nosotros nos descarriamos como ovejas, cada cual se apartó por su camino: mas Jehová cargó en él el pecado de todos nosotros."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"ovelhas"},"fr":{"text":"brebis"},"en":{"text":"sheep"},"es":{"text":"ovejas"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"cabras"},"fr":{"text":"chèvres"},"en":{"text":"goats"},"es":{"text":"cabras"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"lobos"},"fr":{"text":"loups"},"en":{"text":"wolves"},"es":{"text":"lobos"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"bois"},"fr":{"text":"bœufs"},"en":{"