select public.upsert_bank_question($json${"id":"poet-medium-019","type":"verse","level":"medium","testament":"ot","book":"LAM","chapter":3,"verse_start":22,"verse_end":23,"texts":{"pt":{"prompt":"É pelas bondades do SENHOR que não somos consumidos, porque suas misericórdias não têm fim. Elas são novas a cada _____; grande é a tua fidelidade.","bible_ref":"Lamentações 3:22-23","verse_text":"É pelas bondades do SENHOR que não somos consumidos, porque suas misericórdias não têm fim. Elas são novas a cada manhã; grande é a tua fidelidade."},"fr":{"prompt":"Les bontés de l’Éternel ne sont pas épuisées, Ses compassions ne sont pas à leur terme; Elles se renouvellent chaque _____. Oh! Que ta fidélité est grande!","bible_ref":"Lamentations 3:22-23","verse_text":"Les bontés de l’Éternel ne sont pas épuisées, Ses compassions ne sont pas à leur terme; Elles se renouvellent chaque matin. Oh! Que ta fidélité est grande!"},"en":{"prompt":"It is of the LORD’s mercies that we are not consumed, because his compassions fail not. They are new every _____: great is thy faithfulness.","bible_ref":"Lamentations 3:22-23","verse_text":"It is of the LORD’s mercies that we are not consumed, because his compassions fail not. They are new every morning: great is thy faithfulness."},"es":{"prompt":"Es por la misericordia de Jehová que no somos consumidos, porque nunca decayeron sus misericordias. Nuevas son cada _____; grande es tu fidelidad.","bible_ref":"Lamentaciones 3:22-23","verse_text":"Es por la misericordia de Jehová que no somos consumidos, porque nunca decayeron sus misericordias. Nuevas son cada mañana; grande es tu fidelidad."}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"hora"},"fr":{"text":"heure"},"en":{"text":"hour"},"es":{"text":"hora"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"semana"},"fr":{"text":"semaine"},"en":{"text":"week"},"es":{"text":"semana"}}},{"position":3,"is_correct":true,"texts":{"pt":{"text":"manhã"},"fr":{"text":"matin"},