select public.upsert_bank_question($json${"id":"poet-medium-020","type":"verse","level":"medium","testament":"ot","book":"HAB","chapter":2,"verse_start":4,"verse_end":4,"texts":{"pt":{"prompt":"Eis que o soberbo não tem a alma correta em si; mas o justo viverá por sua _____.","bible_ref":"Habacuque 2:4","verse_text":"Eis que o soberbo não tem a alma correta em si; mas o justo viverá por sua fé."},"fr":{"prompt":"Voici, son âme s’est enflée, elle n’est pas droite en lui; Mais le juste vivra par sa _____.","bible_ref":"Habacuc 2:4","verse_text":"Voici, son âme s’est enflée, elle n’est pas droite en lui; Mais le juste vivra par sa foi."},"en":{"prompt":"Behold, his soul which is lifted up is not upright in him: but the just shall live by his _____.","bible_ref":"Habakkuk 2:4","verse_text":"Behold, his soul which is lifted up is not upright in him: but the just shall live by his faith."},"es":{"prompt":"He aquí se enorgullece aquel cuya alma no es derecha en él: mas el justo en su _____ vivirá.","bible_ref":"Habacuc 2:4","verse_text":"He aquí se enorgullece aquel cuya alma no es derecha en él: mas el justo en su fe vivirá."}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"força"},"fr":{"text":"force"},"en":{"text":"strength"},"es":{"text":"fuerza"}}},{"position":2,"is_correct":true,"texts":{"pt":{"text":"fé"},"fr":{"text":"foi"},"en":{"text":"faith"},"es":{"text":"fe"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"lei"},"fr":{"text":"loi"},"en":{"text":"law"},"es":{"text":"ley"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"espada"},"fr":{"text":"épée"},"en":{"text":"sword"},"es":{"text":"espada"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"poet-hard-001","type":"choice","level":"hard","testament":"ot","book":"JOB","chapter":2,"verse_start":11,"verse_end":11,"texts":{"pt":{"prompt":"Qual dos três amigos que vieram consolar Jó era de Temã?","bible_ref":"Jó 2:11","verse_text":"Quando três amigos de Jó, Elifaz temanita, Bildade suíta, e Zofar naamita, ouviram todo este mal que lhe tinha vindo sobre ele, vieram cada um de seu lugar; porque haviam combinado de juntamente virem para se condoerem dele, e o consolarem."},"fr":{"prompt":"Lequel des trois amis venus consoler Job était de Théman ?","bible_ref":"Job 2:11","verse_text":"Trois amis de Job, Éliphaz de Théman, Bildad de Schuach, et Tsophar de Naama, apprirent tous les malheurs qui lui étaient arrivés. Ils se concertèrent et partirent de chez eux pour aller le plaindre et le consoler!"},"en":{"prompt":"Which of the three friends who came to comfort Job was the Temanite?","bible_ref":"Job 2:11","verse_text":"Now when Job’s three friends heard of all this evil that was come upon him, they came every one from his own place; Eliphaz the Temanite, and Bildad the Shuhite, and Zophar the Naamathite: for they had made an appointment together to come to mourn with him and to comfort him."},"es":{"prompt":"¿Cuál de los tres amigos que vinieron a consolar a Job era temanita?","bible_ref":"Job 2:11","verse_text":"Y tres amigos de Job, Eliphaz Temanita, y Bildad Suhita, y Sophar Naamathita, luego que oyeron todo este mal que le había sobrevenido, vinieron cada uno de su lugar; porque habían concertado de venir juntos á condolecerse de él, y á consolarle."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Elifaz"},"fr":{"text":"Éliphaz"},"en":{"text":"Eliphaz"},"es":{"text":"Eliphaz"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Bildade"},"fr":{"text":"Bildad"},"en":{"text":"Bildad"},"es":{"text":"Bildad"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Zofar"},"fr":{"text":"Tsophar"},"en":{"text":"Zophar"},"es":{"text":"Sophar"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Eliú"},"fr":{"text":"Élihu"},"en":{"text":"Elihu"},"es":{"text":"Eliú"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"poet-hard-002","type":"choice","level":"hard","testament":"ot","book":"DAN","chapter":1,"verse_start":7,"verse_end":7,"texts":{"pt":{"prompt":"Que nome deu o chefe dos eunucos a Daniel na Babilónia?","bible_ref":"Daniel 1:7","verse_text":"Aos quais o chefe dos eunucos pôs outros nomes: a Daniel, Beltessazar; a Ananias, Sadraque; a Misael, Mesaque; e a Azarias, Abednego."},"fr":{"prompt":"Quel nom le chef des eunuques donna-t-il à Daniel à Babylone ?","bible_ref":"Daniel 1:7","verse_text":"Le chef des eunuques leur donna des noms, à Daniel celui de Beltschatsar, à Hanania celui de Schadrac, à Mischaël celui de Méschac, et à Azaria celui d’Abed-Nego."},"en":{"prompt":"What name did the prince of the eunuchs give to Daniel in Babylon?","bible_ref":"Daniel 1:7","verse_text":"Unto whom the prince of the eunuchs gave names: for he gave unto Daniel the name of Belteshazzar; and to Hananiah, of Shadrach; and to Mishael, of Meshach; and to Azariah, of Abed-nego."},"es":{"prompt":"¿Qué nombre puso el príncipe de los eunucos a Daniel en Babilonia?","bible_ref":"Daniel 1:7","verse_text":"A los cuales el príncipe de los eunucos puso nombres: y puso á Daniel, Beltsasar; y á Ananías, Sadrach; y á Misael, Mesach; y á Azarías, Abed-nego."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Beltessazar"},"fr":{"text":"Beltschatsar"},"en":{"text":"Belteshazzar"},"es":{"text":"Beltsasar"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Belsazar"},"fr":{"text":"Belschatsar"},"en":{"text":"Belshazzar"},"es":{"text":"Belsasar"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Sadraque"},"fr":{"text":"Schadrac"},"en":{"text":"Shadrach"},"es":{"text":"Sadrach"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Abednego"},"fr":{"text":"Abed-Nego"},"en":{"text":"Abed-nego"},"es":{"text":"Abed-nego"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"poet-hard-003","type":"choice","level":"hard","testament":"ot","book":"HOS","chapter":1,"verse_start":3,"verse_end":3,"texts":{"pt":{"prompt":"Com quem casou o profeta Oseias?","bible_ref":"Oseias 1:3","verse_text":"Então ele foi, e tomou a Gômer, filha de Diblaim, a qual concebeu, e lhe deu à luz um filho."},"fr":{"prompt":"Qui le prophète Osée prit-il pour femme ?","bible_ref":"Osée 1:3","verse_text":"Il alla, et il prit Gomer, fille de Diblaïm. Elle conçut, et lui enfanta un fils."},"en":{"prompt":"Whom did the prophet Hosea take as his wife?","bible_ref":"Hosea 1:3","verse_text":"So he went and took Gomer the daughter of Diblaim; which conceived, and bare him a son."},"es":{"prompt":"¿Con quién se casó el profeta Oseas?","bible_ref":"Oseas 1:3","verse_text":"Fué pues, y tomó á Gomer hija de Diblaim, la cual concibió y le parió un hijo."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Gómer, filha de Diblaim"},"fr":{"text":"Gomer, fille de Diblaïm"},"en":{"text":"Gomer, the daughter of Diblaim"},"es":{"text":"Gomer, hija de Diblaim"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Mical, filha de Saul"},"fr":{"text":"Mical, fille de Saül"},"en":{"text":"Michal, the daughter of Saul"},"es":{"text":"Michâl, hija de Saúl"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Orfa, a moabita"},"fr":{"text":"Orpa, la Moabite"},"en":{"text":"Orpah, the Moabitess"},"es":{"text":"Orpha, la moabita"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Abigail, mulher de Nabal"},"fr":{"text":"Abigaïl, femme de Nabal"},"en":{"text":"Abigail, Nabal’s wife"},"es":{"text":"Abigail, mujer de Nabal"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"poet-hard-004","type":"choice","level":"hard","testament":"ot","book":"AMO","chapter":7,"verse_start":14,"verse_end":14,"texts":{"pt":{"prompt":"Antes de ser profeta, qual era o trabalho de Amós, segundo o que disse a Amazias?","bible_ref":"Amós 7:14","verse_text":"Então Amós respondeu a Amazias: Eu não era profeta, nem filho de profeta; mas eu era criador de gado, e colhedor de frutos de sicômoros."},"fr":{"prompt":"Avant d’être prophète, quel était le métier d’Amos, d’après sa réponse à Amatsia ?","bible_ref":"Amos 7:14","verse_text":"Amos répondit à Amatsia: Je ne suis ni prophète, ni fils de prophète; mais je suis berger, et je cultive des sycomores."},"en":{"prompt":"Before he was a prophet, what was Amos’s work, as he told Amaziah?","bible_ref":"Amos 7:14","verse_text":"Then answered Amos, and said to Amaziah, I was no prophet, neither was I a prophet’s son; but I was an herdman, and a gatherer of sycomore fruit:"},"es":{"prompt":"Antes de ser profeta, ¿cuál era el oficio de Amós, según dijo a Amasías?","bible_ref":"Amós 7:14","verse_text":"Entonces respondió Amós, y dijo á Amasías: No soy profeta, ni soy hijo de profeta, sino que soy boyero, y cogedor de cabrahigos:"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Criador de gado"},"fr":{"text":"Berger"},"en":{"text":"A herdman"},"es":{"text":"Boyero"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Pescador"},"fr":{"text":"Pêcheur"},"en":{"text":"A fisherman"},"es":{"text":"Pescador"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Sacerdote"},"fr":{"text":"Prêtre"},"en":{"text":"A priest"},"es":{"text":"Sacerdote"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Escriba"},"fr":{"text":"Scribe"},"en":{"text":"A scribe"},"es":{"text":"Escriba"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"poet-hard-005","type":"choice","level":"hard","testament":"ot","book":"OBA","chapter":1,"verse_start":1,"verse_end":1,"texts":{"pt":{"prompt":"Sobre que povo é a visão de Obadias?","bible_ref":"Obadias 1:1","verse_text":"Visão de Obadias. Assim diz o Senhor DEUS quanto a Edom: Temos ouvido notícias do SENHOR, e mensageiro foi enviado entre as nações; levantai-vos, e nos levantaremos em batalha contra ela."},"fr":{"prompt":"Sur quel peuple porte la prophétie d’Abdias ?","bible_ref":"Abdias 1:1","verse_text":"Prophétie d’Abdias. Ainsi parle le Seigneur, l’Éternel, sur Édom: Nous avons appris une nouvelle de la part de l’Éternel, Et un messager a été envoyé parmi les nations: Levez-vous, marchons contre Édom pour lui faire la guerre!"},"en":{"prompt":"Which nation is the vision of Obadiah about?","bible_ref":"Obadiah 1:1","verse_text":"The vision of Obadiah. Thus saith the Lord GOD concerning Edom; We have heard a rumour from the LORD, and an ambassador is sent among the heathen, Arise ye, and let us rise up against her in battle."},"es":{"prompt":"¿Sobre qué pueblo es la visión de Abdías?","bible_ref":"Abdías 1:1","verse_text":"Visión de Abdías. El Señor Jehová ha dicho así cuanto á Edom: Oído hemos el pregón de Jehová, y mensajero es enviado á las gentes. Levantaos, y levantémonos contra ella en batalla."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Edom"},"fr":{"text":"Édom"},"en":{"text":"Edom"},"es":{"text":"Edom"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Moabe"},"fr":{"text":"Moab"},"en":{"text":"Moab"},"es":{"text":"Moab"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Amom"},"fr":{"text":"Ammon"},"en":{"text":"Ammon"},"es":{"text":"Ammón"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Os filisteus"},"fr":{"text":"Les Philistins"},"en":{"text":"The Philistines"},"es":{"text":"Los filisteos"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"poet-hard-006","type":"choice","level":"hard","testament":"ot","book":"ZEP","chapter":1,"verse_start":1,"verse_end":1,"texts":{"pt":{"prompt":"Nos dias de que rei de Judá veio a palavra do SENHOR a Sofonias?","bible_ref":"Sofonias 1:1","verse_text":"Palavra do SENHOR que veio a Sofonias filho de Cuxi, filho de Gedalias, filho de Amarias, filho de Ezequias, nos dias de Josias filho de Amom, rei de Judá."},"fr":{"prompt":"Au temps de quel roi de Juda la parole de l’Éternel fut-elle adressée à Sophonie ?","bible_ref":"Sophonie 1:1","verse_text":"La parole de l’Éternel qui fut adressée à Sophonie, fils de Cuschi, fils de Guedalia, fils d’Amaria, fils d’Ézéchias, au temps de Josias, fils d’Amon, roi de Juda."},"en":{"prompt":"In the days of which king of Judah did the word of the LORD come to Zephaniah?","bible_ref":"Zephaniah 1:1","verse_text":"The word of the LORD which came unto Zephaniah the son of Cushi, the son of Gedaliah, the son of Amariah, the son of Hizkiah, in the days of Josiah the son of Amon, king of Judah."},"es":{"prompt":"¿En días de qué rey de Judá vino la palabra de Jehová a Sofonías?","bible_ref":"Sofonías 1:1","verse_text":"Palabra de Jehová que fué á Sofonías hijo de Cushi, hijo de Gedalías, hijo de Amarías, hijo de Ezechîas, en días de Josías hijo de Amón, rey de Judá."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Josias"},"fr":{"text":"Josias"},"en":{"text":"Josiah"},"es":{"text":"Josías"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Manassés"},"fr":{"text":"Manassé"},"en":{"text":"Manasseh"},"es":{"text":"Manasés"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Uzias"},"fr":{"text":"Ozias"},"en":{"text":"Uzziah"},"es":{"text":"Uzzías"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Acaz"},"fr":{"text":"Achaz"},"en":{"text":"Ahaz"},"es":{"text":"Achâz"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"poet-hard-007","type":"choice","level":"hard","testament":"ot","book":"HAG","chapter":1,"verse_start":1,"verse_end":1,"texts":{"pt":{"prompt":"Quem era o governador de Judá a quem foi dirigida a palavra do SENHOR por meio de Ageu?","bible_ref":"Ageu 1:1","verse_text":"No segundo ano do rei Dario, no sexto mês, no primeiro dia do mês, veio a palavra do SENHOR, por meio do profeta Ageu, a Zorobabel filho de Sealtiel, governador de Judá, e a Josué filho de Jeozadaque, sumo sacerdote, dizendo:"},"fr":{"prompt":"Qui était le gouverneur de Juda à qui fut adressée la parole de l’Éternel par Aggée ?","bible_ref":"Aggée 1:1","verse_text":"La seconde année du roi Darius, le premier jour du sixième mois, la parole de l’Éternel fut adressée par Aggée, le prophète, à Zorobabel, fils de Schealthiel, gouverneur de Juda, et à Josué, fils de Jotsadak, le souverain sacrificateur, en ces mots:"},"en":{"prompt":"Who was the governor of Judah to whom the word of the LORD came by Haggai?","bible_ref":"Haggai 1:1","verse_text":"In the second year of Darius the king, in the sixth month, in the first day of the month, came the word of the LORD by Haggai the prophet unto Zerubbabel the son of Shealtiel, governor of Judah, and to Joshua the son of Josedech, the high priest, saying,"},"es":{"prompt":"¿Quién era el gobernador de Judá a quien vino la palabra de Jehová por medio de Haggeo?","bible_ref":"Hageo 1:1","verse_text":"En el año segundo del rey Darío en el mes sexto, en el primer día del mes, fué palabra de Jehová, por mano del profeta Haggeo, á Zorobabel hijo de Sealtiel, gobernador de Judá, y á Josué hijo de Josadac, gran sacerdote, diciendo:"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Zorobabel"},"fr":{"text":"Zorobabel"},"en":{"text":"Zerubbabel"},"es":{"text":"Zorobabel"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Neemias"},"fr":{"text":"Néhémie"},"en":{"text":"Nehemiah"},"es":{"text":"Nehemías"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Esdras"},"fr":{"text":"Esdras"},"en":{"text":"Ezra"},"es":{"text":"Esdras"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Gedalias"},"fr":{"text":"Guedalia"},"en":{"text":"Gedaliah"},"es":{"text":"Gedalías"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"poet-hard-008","type":"choice","level":"hard","testament":"ot","book":"EZK","chapter":1,"verse_start":3,"verse_end":3,"texts":{"pt":{"prompt":"Junto a que rio estava Ezequiel quando veio a ele a palavra do SENHOR?","bible_ref":"Ezequiel 1:3","verse_text":"verdadeiramente veio a palavra do SENHOR ao sacerdote Ezequiel, filho de Buzi, na terra dos caldeus, junto ao rio Quebar; e ali a mão do SENHOR esteve sobre ele."},"fr":{"prompt":"Près de quel fleuve était Ézéchiel quand la parole de l’Éternel lui fut adressée ?","bible_ref":"Ézéchiel 1:3","verse_text":"la parole de l’Éternel fut adressée à Ézéchiel, fils de Buzi, le sacrificateur, dans le pays des Chaldéens, près du fleuve du Kebar; et c’est là que la main de l’Éternel fut sur lui."},"en":{"prompt":"By which river was Ezekiel when the word of the LORD came to him?","bible_ref":"Ezekiel 1:3","verse_text":"The word of the LORD came expressly unto Ezekiel the priest, the son of Buzi, in the land of the Chaldeans by the river Chebar; and the hand of the LORD was there upon him."},"es":{"prompt":"¿Junto a qué río estaba Ezequiel cuando vino a él la palabra de Jehová?","bible_ref":"Ezequiel 1:3","verse_text":"Fué palabra de Jehová á Ezequiel sacerdote, hijo de Buzi, en la tierra de los Caldeos, junto al río de Chebar; fué allí sobre él la mano de Jehová."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Quebar"},"fr":{"text":"Kebar"},"en":{"text":"Chebar"},"es":{"text":"Chebar"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Jordão"},"fr":{"text":"Jourdain"},"en":{"text":"Jordan"},"es":{"text":"Jordán"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Eufrates"},"fr":{"text":"Euphrate"},"en":{"text":"Euphrates"},"es":{"text":"Eufrates"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Quisom"},"fr":{"text":"Kison"},"en":{"text":"Kishon"},"es":{"text":"Cisón"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"poet-hard-009","type":"choice","level":"hard","testament":"ot","book":"JER","chapter":38,"verse_start":7,"verse_end":7,"texts":{"pt":{"prompt":"Que eunuco da casa do rei soube que Jeremias tinha sido posto na cisterna?","bible_ref":"Jeremias 38:7","verse_text":"E Ebede-Meleque, o cuxita, um eunuco que estava na casa do rei, tendo ouvido que haviam posto Jeremias na cisterna, e estando o rei sentado à porta de Benjamim,"},"fr":{"prompt":"Quel eunuque de la maison du roi apprit qu’on avait mis Jérémie dans la citerne ?","bible_ref":"Jérémie 38:7","verse_text":"Ébed-Mélec, l’Éthiopien, eunuque qui était dans la maison du roi, apprit qu’on avait mis Jérémie dans la citerne. Le roi était assis à la porte de Benjamin."},"en":{"prompt":"Which eunuch of the king’s house heard that Jeremiah had been put in the dungeon?","bible_ref":"Jeremiah 38:7","verse_text":"Now when Ebed-melech the Ethiopian, one of the eunuchs which was in the king’s house, heard that they had put Jeremiah in the dungeon; the king then sitting in the gate of Benjamin;"},"es":{"prompt":"¿Qué eunuco de la casa del rey oyó que habían puesto a Jeremías en la mazmorra?","bible_ref":"Jeremías 38:7","verse_text":"Y oyendo Ebed-melec, hombre etiope, eunuco que estaba en casa del rey, que habían puesto á Jeremías en la mazmorra, y estando sentado el rey á la puerta de Benjamín,"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Ebede-Meleque"},"fr":{"text":"Ébed-Mélec"},"en":{"text":"Ebed-melech"},"es":{"text":"Ebed-melec"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Baruque"},"fr":{"text":"Baruc"},"en":{"text":"Baruch"},"es":{"text":"Baruch"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Jeudi"},"fr":{"text":"Jehudi"},"en":{"text":"Jehudi"},"es":{"text":"Jehudí"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Pasur"},"fr":{"text":"Paschhur"},"en":{"text":"Pashur"},"es":{"text":"Pashur"}}}]}$json$::jsonb);
