About 40,000"},"es":{"text":"Unas 40 000"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Cerca de 12 mil"},"fr":{"text":"Environ 12 000"},"en":{"text":"About 12,000"},"es":{"text":"Unas 12 000"}}}]}$json$::jsonb);
