select public.upsert_bank_question($json${"id":"poet-hard-017","type":"verse","level":"hard","testament":"ot","book":"ZEC","chapter":4,"verse_start":6,"verse_end":6,"texts":{"pt":{"prompt":"E ele falou comigo, dizendo: Esta é palavra do SENHOR a Zorobabel, que diz: Não se fará por força, nem por violência, mas sim por meu _____, diz o SENHOR dos exércitos.","bible_ref":"Zacarias 4:6","verse_text":"E ele falou comigo, dizendo: Esta é palavra do SENHOR a Zorobabel, que diz: Não se fará por força, nem por violência, mas sim por meu espírito, diz o SENHOR dos exércitos."},"fr":{"prompt":"Alors il reprit et me dit: C’est ici la parole que l’Éternel adresse à Zorobabel: Ce n’est ni par la puissance ni par la force, mais c’est par mon _____, dit l’Éternel des armées.","bible_ref":"Zacharie 4:6","verse_text":"Alors il reprit et me dit: C’est ici la parole que l’Éternel adresse à Zorobabel: Ce n’est ni par la puissance ni par la force, mais c’est par mon esprit, dit l’Éternel des armées."},"en":{"prompt":"Then he answered and spake unto me, saying, This is the word of the LORD unto Zerubbabel, saying, Not by might, nor by power, but by my _____, saith the LORD of hosts.","bible_ref":"Zechariah 4:6","verse_text":"Then he answered and spake unto me, saying, This is the word of the LORD unto Zerubbabel, saying, Not by might, nor by power, but by my spirit, saith the LORD of hosts."},"es":{"prompt":"Entonces respondió y hablóme, diciendo: Esta es palabra de Jehová á Zorobabel, en que se dice: No con ejército, ni con fuerza, sino con mi _____, ha dicho Jehová de los ejércitos.","bible_ref":"Zacarías 4:6","verse_text":"Entonces respondió y hablóme, diciendo: Esta es palabra de Jehová á Zorobabel, en que se dice: No con ejército, ni con fuerza, sino con mi espíritu, ha dicho Jehová de los ejércitos."}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"braço"},"fr":{"text":"bras"},"en":{"text":"arm"},"es":{"text":"brazo"}}},{"position":2,"is_correct":false,"texts":{